{
 "summary": "The Lean theorem proves two things. First, for every real C > 0 there are n > 0 and a nonconstant function f : {±1}^n → {±1} (encoded as Bool-valued inputs and ℝ-valued outputs in {−1, 1}) whose signed sum of singleton Fourier coefficients exceeds C·√deg(f). Second, the set of ratios Σ_i|f̂({i})|/√deg(f), taken over Boolean f with deg(f) > 0, is not bounded above. The definitions of the uniform average, the characters, the Fourier coefficients and the real Fourier degree (sup of |S| over nonzero f̂(S), which is 0 for constants) match the paper. I found no material caveat: the junk-value risks (division, empty sup, cardinality zero) are all neutralized by the hypotheses or are harmless.",
 "glossary": [
  {"decl": "Cube", "line": 16, "plain": "{−1,1}^ι, encoded as ι → Bool", "standard_concept": "Boolean sign cube", "matches_standard": "yes", "note": ""},
  {"decl": "sign", "line": 18, "plain": "false ↦ +1, true ↦ −1", "standard_concept": "±1 encoding of bits", "matches_standard": "yes", "note": ""},
  {"decl": "average", "line": 20, "plain": "uniform expectation E over a finite type", "standard_concept": "uniform expectation", "matches_standard": "yes", "note": "The cube has cardinality 2^n ≥ 1, so the inverse of the cardinality is never junk."},
  {"decl": "character", "line": 23, "plain": "χ_S(x) = ∏_{i∈S} x_i", "standard_concept": "Fourier–Walsh character", "matches_standard": "yes", "note": ""},
  {"decl": "fourierCoeff", "line": 26, "plain": "f̂(S) = E[f(X) ∏_{i∈S} X_i]", "standard_concept": "Fourier coefficient", "matches_standard": "yes", "note": ""},
  {"decl": "fourierDegree", "line": 30, "plain": "deg(f) = max{|S| : f̂(S) ≠ 0}, and 0 if there is no such S", "standard_concept": "real multilinear degree", "matches_standard": "yes", "note": "An empty sup gives 0, matching 'constants have degree zero'."},
  {"decl": "IsBoolean", "line": 34, "plain": "f takes only the values ±1", "standard_concept": "Boolean function into {−1,1}", "matches_standard": "yes", "note": ""},
  {"decl": "Nonconstant", "line": 37, "plain": "f takes two different values somewhere", "standard_concept": "nonconstant", "matches_standard": "yes", "note": ""},
  {"decl": "singletonSum", "line": 40, "plain": "Σ_i f̂({i})", "standard_concept": "signed linear Fourier sum", "matches_standard": "yes", "note": ""},
  {"decl": "absoluteSingletonSum", "line": 43, "plain": "Σ_i |f̂({i})|", "standard_concept": "absolute linear Fourier sum", "matches_standard": "yes", "note": ""},
  {"decl": "SignedViolations", "line": 46, "plain": "∀C>0 ∃n>0 ∃ Boolean nonconstant f on n bits with C√deg f < Σ_i f̂({i})", "standard_concept": "first clause of Theorem 1.1", "matches_standard": "yes", "note": ""},
  {"decl": "AbsoluteRatios", "line": 50, "plain": "the set {Σ_i|f̂({i})|/√deg f : n>0, f Boolean, deg f > 0}", "standard_concept": "the set whose supremum appears in Theorem 1.1", "matches_standard": "yes", "note": "deg > 0 makes the denominator positive."}
 ],
 "lean_claims": [
  {"theorem": "main", "line": 57, "plain": "(∀C>0 ∃n>0 ∃f:{±1}^n→{±1} nonconstant with Σ_i f̂({i}) > C√deg(f)) ∧ the set {Σ_i|f̂({i})|/√deg(f) : n≥1, f Boolean, deg(f)>0} is not bounded above in ℝ."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "For every C>0 there are n≥1 and a nonconstant Boolean f with Σ_i f̂({i}) > C√deg(f). Consequently, the supremum over n≥1 and Boolean f with deg(f)>0 of Σ|f̂({i})|/√deg(f) is ∞."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1", "lean_theorem": "OAI.SquareRootDegree.main", "relation": "equivalent", "why": "Both clauses are formalized faithfully. 'Not bounded above' is the real-valued rendering of sup = ∞."}
 ],
 "flags": [],
 "lint_verdicts": [
  {"line": 21, "rule": "card-zero", "verdict": "harmless", "why": "The average is only applied over Cube (Fin n), which has cardinality 2^n ≥ 1."},
  {"line": 32, "rule": "card-zero", "verdict": "harmless", "why": "The empty-sup default of 0 matches the paper's convention that constants have degree zero, and the second clause separately requires deg > 0."},
  {"line": 53, "rule": "junk-div", "verdict": "harmless", "why": "The hypothesis 0 < fourierDegree f makes √deg strictly positive, so the division is never by zero."}
 ]
}
